def __init__(self, config: Any, rag_overrides: Mapping[str, Any] | None = None) -> None:
        self.config = config
        self._rag_overrides = dict(rag_overrides or {})

def shutdown(self, resources: Optional[RuntimeResources]) -> None:
        """Stop schedulers and close clients."""
        if not resources:
            return

        for scheduler, name in [
            (resources.snapshot_scheduler, "snapshot"),
            (resources.cleanup_scheduler, "cleanup"),
            (resources.temporal_cleanup_scheduler, "temporal cleanup"),
        ]:
            if scheduler:
                try:
                    scheduler.stop()
                    log.info("%s scheduler stopped", name)
                except Exception as exc:  # pragma: no cover - optional
                    log.error("Error stopping %s scheduler: %s", name, exc)

        if resources.weaviate_client:
            try:
                resources.weaviate_client.close()
                log.info("Weaviate client closed")
            except Exception as exc:  # pragma: no cover - optional
                log.error("Error closing Weaviate client: %s", exc)

def _resolve_generation_params(options) -> Dict[str, Any]:
    if options is None:
        return {
            "temperature": settings.RAG_DEFAULT_TEMPERATURE,
            "top_k": None,
            "max_tokens": settings.RAG_DEFAULT_MAX_TOKENS
        }

    max_tokens = options.max_tokens or options.num_predict or settings.RAG_DEFAULT_MAX_TOKENS
    return {
        "temperature": options.temperature if options.temperature is not None else settings.RAG_DEFAULT_TEMPERATURE,
        "top_k": options.top_k,
        "max_tokens": max_tokens,
    }

async def embeddings(
    request: OllamaEmbeddingsRequest,
    embed_service=Depends(get_embedding_service),
) -> OllamaEmbeddingsResponse:
    inputs = request.input if isinstance(request.input, list) else [request.input]
    if len(inputs) == 1:
        vectors = [embed_service.generate(inputs[0])]
    else:
        vectors = embed_service.generate_batch(inputs)
    return OllamaEmbeddingsResponse(model=request.model, embeddings=vectors)

