def decorator(factory: GraphBackendFactory) -> GraphBackendFactory:
        normalized = (name or "").strip().lower()
        if not normalized:
            raise ValueError("Graph backend name must be non-empty")
        if not callable(factory):
            raise TypeError("Graph backend factory must be callable")

        with _lock:
            _factories[normalized] = factory

        return factory

def _graph_settings(config, alias: str) -> Mapping[str, Any]:
    stores = getattr(config, "GRAPH_STORES", None) or {}
    if not isinstance(stores, dict):
        raise TypeError("Config.GRAPH_STORES must be a dict mapping aliases to dict settings")
    if alias not in stores:
        available = ", ".join(sorted(stores.keys())) or "<none>"
        raise KeyError(f"Unknown GRAPH_STORES alias '{alias}'. Available: {available}")
    store_cfg = stores[alias]
    if not isinstance(store_cfg, dict):
        raise TypeError(f"Config.GRAPH_STORES['{alias}'] must be a dict of settings")
    return store_cfg

def _iter_payloads(self):
        """
        Internal generator to iterate over payloads in batches from the vector store.
        """
        for payload in self.vector.iter_payloads(batch_size=self.batch_size):
            yield payload

def _process_payload(self, payload: dict) -> bool:
        """
        Process a single payload: apply filters and run NER.
        """
        is_code = payload.get("type") == "code"
        is_text = not is_code

        if self.only_code and not is_code:
            return False
        if self.only_text and not is_text:
            return False

        content = payload.get("content") or payload.get("structure_summary")
        if not content:
            return False

        try:
            self.extractor.process_text(content, payload)
            return True
        except (RequestException, JSONDecodeError, Neo4jError) as e:
            logger.error("NER processing error for payload %s: %s", payload.get("external_id") or payload.get("hash"), e)
            return False

