        self.client: weaviate.WeaviateClient = schema.client

def _is_not_found_error(exc: UnexpectedStatusCodeError) -> bool:
        """Return True when Weaviate indicates a missing object/UUID.

        Handles both:
            - status_code == 404
            - status_code == 500 with body/message including "no object with id '<uuid>'"
        """
        status = getattr(exc, "status_code", None)
        if status == 404:
            return True

        # Try to extract a meaningful error text from the exception.
        text = ""
        for attr in ("message", "body", "response", "response_text", "error"):
            value = getattr(exc, attr, None)
            if value:
                text = str(value)
                break
        if not text:
            text = str(exc)

        low = text.lower()
        return ("no object with id" in low) or ("not found" in low)

def _extract_error_text(exc: Exception) -> str:
        for attr in ("message", "body", "response", "response_text", "error"):
            value = getattr(exc, attr, None)
            if value:
                return str(value)
        return str(exc)

def _update_existing(self, coll, uuid_id: str, payload: Dict[str, Any], vector: List[float]) -> None:
        try:
            coll.data.update(uuid=uuid_id, properties=payload, vector=vector)
        except UnexpectedStatusCodeError as exc:
            if self._is_not_found_error(exc):
                logger.warning(
                    "Weaviate reported not-found while updating uuid=%s; reinserting payload.",
                    uuid_id,
                )
                coll.data.insert(uuid=uuid_id, properties=payload, vector=vector)
                return
            logger.exception("Weaviate update failed for uuid=%s", uuid_id)
            raise
        except Exception:
            logger.exception("Weaviate update failed for uuid=%s", uuid_id)
            raise

def exists(self, point_id: str, tenant_id: Optional[str] = None) -> bool:
        """Check whether a record exists in Weaviate."""
        coll = self._coll(tenant_id)
        uuid_id = self._normalize_uuid(point_id)
        return bool(coll.data.exists(uuid=uuid_id))

def _normalize_uuid(value: Any) -> str:
        import uuid

        try:
            return str(uuid.UUID(str(value)))
        except (ValueError, AttributeError, TypeError):
            return str(uuid.uuid5(uuid.NAMESPACE_URL, str(value)))

def _run_query(active_filters: Optional[Filter]):
            return coll.query.near_vector(
                vector=vector,
                limit=top_k,
                filters=active_filters,
            )

def iter_payloads(self, batch_size: int = 256, tenant_id: Optional[str] = None) -> Iterator[Dict[str, Any]]:
        coll = self._coll(tenant_id)
        cursor: Optional[str] = None

        while True:
            result = coll.query.fetch_objects(limit=batch_size, cursor=cursor)
            objects = getattr(result, "objects", []) or []  # type: ignore[attr-defined]
            if not objects:
                break

            for obj in objects:
                yield getattr(obj, "properties", {}) or {}

            page_info = getattr(result, "page_info", None)
            cursor = getattr(page_info, "end_cursor", None)
            if not getattr(page_info, "has_next_page", False):
                break

def archive_file(self, file_id: str, tenant_id: Optional[str] = None) -> None:
        coll = self._coll(tenant_id)
        where = Filter.by_property("file_id").equal(file_id)
        cursor: Optional[str] = None

        while True:
            result = coll.query.fetch_objects(limit=200, cursor=cursor, filters=where)
            objects = getattr(result, "objects", []) or []  # type: ignore[attr-defined]
            if not objects:
                break

            for obj in objects:
                uuid_id = getattr(obj, "uuid", None)
                if not uuid_id:
                    continue
                coll.data.update(uuid=uuid_id, properties={"archived": True})

            page_info = getattr(result, "page_info", None)
            cursor = getattr(page_info, "end_cursor", None)
            if not getattr(page_info, "has_next_page", False):
                break

def __del__(self) -> None:
        try:
            if hasattr(self, "client") and isinstance(self.client, weaviate.WeaviateClient):
                self.client.close()
        except (AttributeError, TypeError, UnexpectedStatusCodeError, OSError, RuntimeError) as exc:
            logger.debug("Ignoring exception while closing Weaviate client: %s", exc)

def ensure(self) -> None:
        """Ensure the target collection exists; create it if missing."""
        schema = self.client.collections
        existing_classes = schema.list_all()
        existing_names = [c.name if hasattr(c, "name") else str(c) for c in existing_classes]

        if self.class_name not in existing_names:
            self._create_class(schema)

        if self.multitenant_enabled and self.default_tenant:
            self._ensure_default_tenant()

def coll(self, tenant_id: Optional[str]):
        """Get the collection handle, optionally bound to a tenant."""
        collection = self.client.collections.get(self.class_name)
        if not self.multitenant_enabled:
            return collection

        effective_tenant = tenant_id or self.default_tenant
        if not effective_tenant:
            raise RuntimeError(
                "Weaviate multi-tenancy is enabled but no tenant_id was provided. "
                "Set WEAVIATE_DEFAULT_TENANT or pass tenant_id explicitly."
            )
        return collection.with_tenant(str(effective_tenant))

def _ensure_default_tenant(self) -> None:
        """Ensure configured default tenant exists when multi-tenancy is enabled."""
        collection = self.client.collections.get(self.class_name)
        tenants_api = collection.tenants

        try:
            tenants_api.create([self.default_tenant])
        except Exception as exc:
            # We do not want to fail if the tenant already exists.
            if "already exist" not in str(exc).lower():
                raise

def get_metrics(self) -> Dict[str, Any]:
        """Get adapter metrics."""
        return {
            'operation_count': self._operation_count,
            'error_count': self._error_count,
            'pressure_warning_count': self._pressure_warning_count,
            'error_rate': self._error_count / self._operation_count if self._operation_count > 0 else 0.0,
            'service_type': self.service_type.value,
            'default_stage': self.default_stage.value,
        }

