class FallbackUnknownMapper(BaseMapper):
    """Fallback mapper for unknown exceptions."""

    def can_map(self, exception: Exception, context: Dict[str, Any]) -> bool:
        return True  # Always matches as fallback

    def map(self, exception: Exception, context: Dict[str, Any]) -> Union[ErrorEvent, PressureEvent]:
        stage = context.get('stage', ProcessingStage.API)
        service = context.get('service', ServiceType.LLM)

        metadata = {
            'exception_type': type(exception).__name__,
            'exception_message': str(exception),
            'timestamp': time.time(),
            'context': context
        }

        return ErrorEvent(
            kind=ErrorKind.UNKNOWN,
            service=service,
            stage=stage,
            retryable=True,
            severity=Severity.MEDIUM,
            message=f"Unknown error: {exception}",
            metadata=metadata,
            original_exception=exception
        )

def map_exception(
        self, 
        exception: Exception, 
        context: Optional[Dict[str, Any]] = None
    ) -> Union[ErrorEvent, PressureEvent]:
        """
        Map an exception to a standardized event.

        Args:
            exception: The exception to map
            context: Additional context about where/when the error occurred

        Returns:
            Standardized ErrorEvent or PressureEvent
        """
        context = context or {}

        # Try each mapper in order
        for mapper in self.mappers:
            if mapper.can_map(exception, context):
                return mapper.map(exception, context)

        # This should never happen since FallbackUnknownMapper always matches
        raise RuntimeError("No mapper could handle the exception")

def get_default_mapper_chain() -> MapperChain:
    """Get the global default mapper chain."""
    global _default_mapper_chain
    if _default_mapper_chain is None:
        _default_mapper_chain = MapperChain()
    return _default_mapper_chain

def record_success(self) -> None:
        """Record a successful operation."""
        if self.state == "half-open":
            # Success in half-open state closes the circuit
            self.state = "closed"
            self.failure_count = 0
            self.half_open_attempts = 0
        elif self.state == "closed":
            # Reset failure count on success
            self.failure_count = max(0, self.failure_count - 1)

def get_state(self) -> Dict[str, Any]:
        """Get current circuit state."""
        return {
            "state": self.state,
            "failure_count": self.failure_count,
            "last_failure_time": self.last_failure_time,
            "half_open_attempts": self.half_open_attempts,
            "failure_threshold": self.failure_threshold,
            "reset_timeout": self.reset_timeout,
        }

class BaseErrorPolicy(ABC):
    """Base class for error policies (Strategy pattern)."""

    @abstractmethod
    def decide(
        self,
        result: Result[Any, ErrorEvent],
        context: Dict[str, Any]
    ) -> PolicyDecision:
        """Make a decision based on the error result and context."""
        pass

