def get_status(self, name: str) -> Optional[VolumeStatus]:
        """Get the status of a specific volume."""
        return self.volumes.get(name)

def get_all_statuses(self) -> Dict[str, VolumeStatus]:
        """Get statuses of all monitored volumes."""
        return self.volumes.copy()

def _check_volumes(self):
        """Check all monitored volumes for reconnections."""
        for name, config in self.volumes.items():
            # Only check if we're currently using fallback
            if not self._volume_states.get(name, False):
                continue

            # Check if primary has become available
            if self._check_primary_available(config.primary_path):
                logger.info(
                    f"Volume '{name}' has RECONNECTED! "
                    f"Primary volume is now available at {config.primary_path}"
                )

                # Update state
                self._volume_states[name] = False

                # Trigger callback if provided
                if config.on_reconnect:
                    try:
                        logger.info(f"Triggering reconnect callback for '{name}'")
                        config.on_reconnect(config.primary_path)
                    except Exception as e:
                        logger.e... [truncated]

def _watch_loop(self):
        """Main watch loop that runs in background thread."""
        logger.info(
            f"Volume watcher started. Checking every {self.check_interval} seconds."
        )

        while self._running:
            try:
                self._check_volumes()
            except Exception as e:
                logger.error(f"Error in volume watcher: {e}", exc_info=True)

            # Sleep in small intervals to allow quick shutdown
            for _ in range(self.check_interval):
                if not self._running:
                    break
                time.sleep(1)

        logger.info("Volume watcher stopped.")

def stop(self):
        """Stop the background watcher thread."""
        if not self._running:
            return

        logger.info("Stopping volume watcher...")
        self._running = False

        if self._thread:
            self._thread.join(timeout=5)
            self._thread = None

def is_running(self) -> bool:
        """Check if the watcher is currently running."""
        return self._running

def get_service_status(self) -> dict:
        """
        Get detailed status of the failed service.

        Returns:
            Dictionary with service status information
        """
        try:
            result = subprocess.run(
                ['systemctl', '--user', 'status', self.unit_name, '--no-pager'],
                capture_output=True,
                text=True,
                timeout=5
            )

            return {
                'status_output': result.stdout,
                'exit_code': result.returncode
            }
        except Exception as e:
            return {
                'status_output': f'Failed to get status: {e}',
                'exit_code': -1
            }

def find_errors(self, tool: str) -> Dict[str, List[str]]:
        """
        Find error patterns in logs.

        Args:
            tool: Tool name

        Returns:
            Dictionary mapping error categories to matching lines
        """
        logs = self.get_logs(tool)
        errors = defaultdict(list)

        for line in logs.splitlines():
            for pattern, category in self.ERROR_PATTERNS:
                if re.search(pattern, line):
                    errors[category].append(line)

        return dict(errors)

def analyze_all(self) -> Dict[str, Dict]:
        """
        Analyze all configured tools.

        Returns:
            Dictionary mapping tool names to analysis results
        """
        results = {}
        for tool in self.tools:
            results[tool] = self.analyze_tool(tool)
        return results

