    errors: int = 0
    warnings: int = 0
    passed: int = 0

    def add_check(self, result: CheckResult):
        """Add a check result and update counters."""
        self.checks.append(result)
        if result.level == 'error':
            self.errors += 1
        elif result.level == 'warning':
            self.warnings += 1
        elif result.level == 'ok':
            self.passed += 1

