def get_files_in_run(self, run_id: str) -> Set[str]:
        with self.control_plane.get_connection() as conn:
            cursor = conn.execute(
                "SELECT file_path FROM ingest_file_runs WHERE run_id = ?",
                (run_id,),
            )
            return {row[0] for row in cursor.fetchall()}

def get_file_chunk_ids(self, file_path: str) -> List[str]:
        with self.control_plane.get_connection() as conn:
            cursor = conn.execute(
                "SELECT chunk_ids_json FROM files WHERE file_path = ?",
                (file_path,),
            )
            row = cursor.fetchone()
            if not row or not row[0]:
                return []
            try:
                return json.loads(row[0])
            except json.JSONDecodeError:
                return [c for c in str(row[0]).split(",") if c]

def list_consumers(self) -> List[Dict[str, Any]]:
        """List active consumers."""
        with self.control_plane.get_connection() as conn:
            cursor = conn.execute(
                """
                SELECT consumer_name, last_seen, consumer_group
                FROM ingest_consumers
                ORDER BY last_seen DESC
                """
            )
            return [
                {
                    "name": row[0],
                    "last_seen": int(row[1]),
                    "consumer_group": row[2],
                }
                for row in cursor.fetchall()
            ]

