        if self.scheduler_policy == SchedulerPolicy.DFS:
            return len(frontier)
        elif self.scheduler_policy == SchedulerPolicy.BFS:
            return frontier.qsize()
        else:  # PRIORITY
            return len(frontier)

def _checkpoint(self, files: list[str]):
        """Save checkpoint."""
        if not self.metrics or not self.scan_checkpointer:
            return

        self.metrics.last_checkpoint_at = time.time()
        self.metrics.checkpoint_commits_count += 1

        # Update files in checkpoint
        if files and self.current_run_id:
            self.scan_checkpointer.add_discovered_files(self.current_run_id, files)

