def _pattern_variants(pattern_value: str):
        """Yield pattern variants - optimized."""
        yield pattern_value

        stripped = pattern_value.rstrip("/")
        if stripped != pattern_value:
            yield stripped

        for suffix in ("/**", "/**/*"):
            if stripped.endswith(suffix):
                base = stripped[:-len(suffix)].rstrip("/")
                if base:
                    yield base

