        """Convert job to dictionary for serialization."""
        data = {
            "job_id": self.job_id,
            "phase": self.phase.value,
            "run_id": self.run_id,
            "file_path": self.file_path,
            "fingerprint": self.fingerprint,
            "attempt": self.attempt,
            "created_at": self.created_at,
        }

        if self.chunk_id:
            data["chunk_id"] = self.chunk_id

