                row_values = []
                for cell in row.cells:
                    cell_text = cell.text.strip()
                    if cell_text:
                        row_values.append(cell_text)
                _append(" | ".join(row_values))

        return [
            Document(
                page_content="\n".join(lines),
                metadata={"source": self._path},
            )
        ]

