class MarkdownLoader:
    """Loader for markdown files."""
    def __init__(self, path: str):
        self.path = path

    def _clean(self, text: str) -> str:
        text = re.sub(r"!\[.*?\]\(.*?\)", "", text)
        text = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", text)
        return text

    def load(self) -> List[Document]:
        """
        This method removes images and links from the markdown content.

        Returns:
            List[Document]: Loaded documents.
        """
        ensure_file_exists(self.path)
        try:
            result = read_text_with_fallbacks(self.path)
        except ValueError as exc:
            raise LoaderUnreadableTextError(self.path, str(exc)) from exc
        except UnicodeDecodeError as exc:
            raise LoaderUnreadableTextError(self.path, str(exc)) from exc

        cleaned = self._clean(result.text)
        return [Document(page_content=cleaned, metadata={"source": self.path, "encoding": result.encoding})]

def __init__(self, path: str):
        self.path = path
        self._client = OfficeToolClient()
        ensure_file_exists(path)
        ext = Path(path).suffix.lower()
        allowed_exts = {".odt", ".ods", ".odp"}
        if ext and ext not in allowed_exts:
            raise LoaderInvalidFormatError(path, "OpenDocument (.odt/.ods/.odp)")

def _call_convert_service(self, service_url: str, payload: dict) -> dict:
        response = requests.post(
            f"{service_url}/convert",
            json=payload,
            timeout=self.timeout,
        )

        if response.status_code != 200:
            raise RuntimeError(
                f"Office conversion failed (HTTP {response.status_code}): {response.text}"
            )

        result = response.json()

        if not result.get("success"):
            error_msg = result.get("error", "Unknown error")
            raise RuntimeError(f"Office conversion failed: {error_msg}")

        return result

def health_check(self) -> bool:
        """Check if rag-tool-document-processor service is available.

        Returns:
            True if service is healthy, False otherwise
        """
        try:
            response = requests.get(
                f"{self.base_url}/healthz",
                timeout=5,
            )
            return response.status_code == 200
        except Exception:
            return False

def _get_from_cache(self, cache_key: str) -> Optional[List[Document]]:
        """Retrieve cached PDF content."""
        if not self.cache_enabled or not cache_key:
            return None

        try:
            cached_data = self.cache_client.get(cache_key)
            if cached_data is None:
                return None

            # Deserialize documents
            doc_dicts = json.loads(cached_data)
            documents = [
                Document(page_content=d["page_content"], metadata=d["metadata"])
                for d in doc_dicts
            ]
            logger.info(
                "PDF CACHE HIT: Loaded %d pages from cache for %s",
                len(documents),
                Path(self._path).name
            )
            return documents

        except Exception as e:
            logger.debug("PDF cache retrieval error: %s", e)
            return None

def _store_in_cache(
        self, cache_key: str, documents: List[Document]
    ) -> None:
        """Store extracted PDF content in cache."""
        if not self.cache_enabled or not cache_key:
            return

        try:
            # Serialize documents
            doc_dicts = [
                {"page_content": doc.page_content, "metadata": doc.metadata}
                for doc in documents
            ]
            cached_data = json.dumps(doc_dicts)
            self.cache_client.setex(cache_key, self.cache_ttl, cached_data)
            logger.info(
                "PDF CACHE STORE: Cached %d pages for %s (ttl=%ds)",
                len(documents),
                Path(self._path).name,
                self.cache_ttl
            )
        except Exception as e:
            logger.debug("PDF cache storage error: %s", e)

