def _format_timedelta(td):
    """Format timedelta in human-readable form."""
    seconds = int(td.total_seconds())
    if seconds < 60:
        return f"{seconds}s"
    if seconds < 3600:
        minutes = seconds // 60
        return f"{minutes}m"
    if seconds < 86400:
        hours = seconds // 3600
        return f"{hours}h"
    days = seconds // 86400
    return f"{days}d"

