def build_semantic_splitter(options: PipelineOptions) -> Any:
    embeddings = options.semantic_embeddings
    if embeddings is None:
        raise ValueError("semantic_embeddings must be provided for semantic splitting.")

    return SemanticChunker(
        embeddings,
        breakpoint_threshold_type="percentile",
        buffer_size=options.chunk_overlap,
        number_of_chunks=getattr(options, "number_of_chunks", None),
        breakpoint_threshold_amount=getattr(options, "breakpoint_threshold_amount", None),
        add_start_index=True,
    )

class TextSplitter(Protocol):
    """Protocol for splitters that expose split_documents."""
    def split_documents(self, documents: List[Document]) -> List[Document]:
        ...

def _process_markdown_doc(doc: Document, splitter: MarkdownHeaderTextSplitter) -> List[Document]:
    """Process a single document with MarkdownHeaderTextSplitter.

    Centralized logic to avoid duplication across 5+ functions.
    """
    base_meta = doc.metadata or {}
    parts = splitter.split_text(doc.page_content)

    return [
        Document(
            page_content=chunk.page_content,
            metadata=base_meta | (chunk.metadata or {})
        )
        for chunk in parts
    ]

def _split_batch_core(
    splitter: Any,
    documents: Sequence[Document],
    is_markdown: bool,
    has_split_method: bool,
) -> List[Document]:
    """Core splitting logic without I/O or logging.

    Centralized to avoid duplication in batch processing functions.
    """
    if is_markdown:
        chunks: List[Document] = []
        for doc in documents:
            chunks.extend(_process_markdown_doc(doc, splitter))
        return chunks

    if has_split_method:
        return splitter.split_documents(list(documents))

    return list(documents)

def split_documents(
    splitter: Any,
    documents: Sequence[Document]
) -> Iterator[Document]:
    """Basic split without progress."""
    if isinstance(splitter, MarkdownHeaderTextSplitter):
        for doc in documents:
            yield from _process_markdown_doc(doc, splitter)
        return

    if hasattr(splitter, "split_documents"):
        yield from splitter.split_documents(documents)
        return

    yield from documents

def split_documents_fast(
    splitter: Any,
    documents: Sequence[Document],
) -> List[Document]:
    """Fast version without progress for internal use."""
    is_markdown = isinstance(splitter, MarkdownHeaderTextSplitter)
    has_split_method = hasattr(splitter, "split_documents")
    return _split_batch_core(splitter, documents, is_markdown, has_split_method)

def pick_split_policy(self, profile: TextProfile) -> SplitPolicy:
        """Choose split policy based on script.

        Args:
            profile: Output of `profile()`.

        Returns:
            SplitPolicy tuned for the script family.
        """
        if profile.has_cjk or profile.dominant_script in {ScriptFamily.CJK, ScriptFamily.HANGUL}:
            return SplitPolicy(chunk_size=700, chunk_overlap=120, cjk_mode=True)

        return SplitPolicy(chunk_size=1200, chunk_overlap=150, cjk_mode=False)

def normalize(self, text: str) -> str:
        """Normalize unicode for consistent processing."""
        normalized = unicodedata.normalize("NFC", text)
        return normalized.replace("\r\n", "\n").replace("\r", "\n")

def _classify_char(self, character: str) -> ScriptFamily:
        """Classify a character into a script family."""
        code = ord(character)

        # CJK Unified Ideographs + extensions (rough)
        if (0x4E00 <= code <= 0x9FFF) or (0x3400 <= code <= 0x4DBF) or (0x20000 <= code <= 0x2A6DF):
            return ScriptFamily.CJK
        # Hiragana / Katakana
        if (0x3040 <= code <= 0x309F) or (0x30A0 <= code <= 0x30FF):
            return ScriptFamily.CJK
        # Hangul
        if 0xAC00 <= code <= 0xD7AF:
            return ScriptFamily.HANGUL
        # Cyrillic
        if 0x0400 <= code <= 0x04FF or 0x0500 <= code <= 0x052F:
            return ScriptFamily.CYRILLIC
        # Arabic
        if 0x0600 <= code <= 0x06FF or 0x0750 <= code <= 0x077F:
            return ScriptFamily.ARABIC
        # Latin (basic + extended)
        if (0x0041 <= code <= 0x024F) or (0x1E00 <= code <= 0x1EFF):
            return ScriptFamily.LATIN

        return ScriptFamily.OTHER

def _to_shares(self, counts: Dict[ScriptFamily, int], total: int) -> Dict[ScriptFamily, float]:
        """Convert counts to percentage shares."""
        if total <= 0:
            return {}
        return {script: (count / total) for script, count in counts.items()}

def _dominant(self, shares: Dict[ScriptFamily, float]) -> ScriptFamily:
        """Find the dominant script family."""
        if not shares:
            return ScriptFamily.UNKNOWN
        return max(shares.items(), key=lambda item: item[1])[0]

def flush() -> None:
            nonlocal buffer, buffer_length
            if not buffer:
                return
            chunk = "".join(buffer).strip()
            if chunk:
                chunks.append(chunk)
            buffer = []
            buffer_length = 0

