def _reuse_preprocess_status(
        self,
        file_path: str,
        phase_manager: PhaseManager,
    ) -> Optional[PreprocessedFileRecord]:
        status = phase_manager.get_preprocess_status(file_path)
        if not status:
            return None

        if status.get("status") == "ok":
            processed_path = status.get("processed_path") or file_path
            if Path(processed_path).exists():
                return PreprocessedFileRecord(
                    original_path=file_path,
                    processed_path=processed_path,
                    metadata={"resumed": True},
                )
        return None

def _should_skip_failed(self, phase_manager: PhaseManager, file_path: str) -> bool:
        status = phase_manager.get_preprocess_status(file_path)
        if not status:
            return False
        return status.get("status") == "failed" and not self._should_retry_failed()

def _enumerate_directory(self, directory: str) -> List[str]:
        """List all files under the directory for further processing."""
        root = Path(directory)
        if not root.is_dir():
            return []
        return [str(path) for path in root.rglob("*") if path.is_file()]

def _prepare_pipeline_workers(self, pipeline: IngestionPipeline, workers: int) -> None:
        """Adjust the pipeline's worker count for the ingestion phase."""
        pipeline._max_workers = max(1, workers)

def _run_ingestion(
        self,
        pipeline: IngestionPipeline,
        file_paths: List[str],
        options: IngestionOptions,
        phase_manager: PhaseManager,
    ) -> dict:
        """Run ingestion using resumable queue when configured."""
        use_resumable = bool(
            getattr(self.config, "INGESTION_RESUMABLE_ENABLED", False) and getattr(pipeline, "ingest_queue", None)
        )
        if not use_resumable:
            return pipeline.process_batch(file_paths, options)

        pipeline.start_ingestion_run()
        try:
            ingested, failed, enqueued = pipeline.ingest_files_resumable(
                file_paths,
                run_id=phase_manager.run_id,
            )
            return {
                "processed_files": ingested + failed,
                "ingested": ingested,
                "failed": failed,
                "enqueued": enqueued,
            }
        finally:
            pipeline.finish_ingestion_run()

def select_strategy(
    config: object,
    cache_manager: IngestionCacheManager | None,
    strategy_override: Optional[str] = None,
    max_ram_override: Optional[int] = None,
) -> IngestionStrategy:
    """Return the best strategy for the current configuration."""
    requested = (strategy_override or getattr(config, "INGESTION_STRATEGY", "auto") or "auto").lower()

    if requested == "auto":
        requested = _auto_detect(config, max_ram_override)

    strategy_cls = STRATEGY_REGISTRY.get(requested, HighMemoryStrategy)
    return strategy_cls(config, cache_manager)

def _auto_detect(config: object, max_ram_override: Optional[int] = None) -> str:
    profile = getattr(config, "RAG_PERFORMANCE_PROFILE", None) or getattr(config, "RESOURCE_MODE", None)
    if isinstance(profile, str):
        normalized = profile.lower()
        if normalized in {"performance", "high", "balanced"}:
            return "high_memory"
        if normalized in {"optimized", "low_memory", "low"}:
            return "low_memory"

    threshold = max_ram_override if max_ram_override is not None else getattr(config, "MAX_RAM_USAGE_PERCENT", 80)
    if _has_enough_ram(threshold):
        return "high_memory"

    return "low_memory"

def _has_enough_ram(max_usage_percent: int) -> bool:
    try:
        import psutil  # type: ignore[import]
    except ImportError:
        return True

    try:
        memory = psutil.virtual_memory()
        return memory.percent <= max_usage_percent
    except Exception:
        return True

