def resolve_level(level: str | int | None) -> int:
    """Convert a string/int level into a logging level constant."""
    if isinstance(level, int):
        return level
    if isinstance(level, str):
        return getattr(logging, level.upper(), logging.INFO)
    return logging.INFO

