            total = result.total_count if result else 0

            return {
                "collection": self.collection_name,
                "tenant": self.tenant,
                "total_documents": total,
                "top_k": self.top_k,
                "alpha": self.alpha,
            }
        except Exception as e:
            log.error("Failed to get collection stats: %s", e)
            return {"error": str(e)}

