class _Tee:
    """Simple stdout/collector tee to show live output and keep assertions."""

    def __init__(self, *streams):
        self.streams = streams

    def write(self, data):
        for stream in self.streams:
            stream.write(data)

    def flush(self):
        for stream in self.streams:
            flush = getattr(stream, "flush", None)
            if flush:
                flush()

