def prune_old_logs(out_dir: Path, retention_hours: int) -> None:
    """Delete log files older than retention period.

    Args:
        out_dir: Directory containing log files.
        retention_hours: Maximum age in hours to keep files.

    Note:
        Silently skips files that can't be read or deleted.
    """
    cutoff = dt.datetime.now() - dt.timedelta(hours=retention_hours)
    for path in out_dir.glob("*.log"):
        try:
            mtime = dt.datetime.fromtimestamp(path.stat().st_mtime)
        except OSError:
            continue
        if mtime < cutoff:
            try:
                path.unlink()
            except OSError:
                continue

def create_backup(self):
        """Crea backup del proyecto antes de migración"""
        if self.dry_run:
            self.log(f"[DRY-RUN] Crearía backup en: {self.backup_dir}", "DRY")
            return

        self.log("Creando backup del proyecto...", "INFO")
        try:
            # Backup solo de src/ y archivos de config importantes
            shutil.copytree(self.src, self.backup_dir / "src",
                          ignore=shutil.ignore_patterns('__pycache__', '*.pyc', '.mypy_cache'))

            # Backup de archivos raíz importantes
            for file in ["settings.py", "manage.py", ".env"]:
                src_file = self.root / file
                if src_file.exists():
                    shutil.copy2(src_file, self.backup_dir / file)

            self.log(f"Backup creado en: {self.backup_dir}", "SUCCESS")
        except Exception as e:
            self.log(f"Error creando backup: {e}", "ERROR")
            raise

def rollback(self):
        """Revierte cambios desde backup más reciente"""
        backups = sorted(self.root.glob("backup_*"), reverse=True)
        if not backups:
            self.log("No hay backups disponibles", "ERROR")
            return False

        latest_backup = backups[0]
        self.log(f"Revirtiendo desde backup: {latest_backup}", "INFO")

        try:
            # Restaurar src/
            if (latest_backup / "src").exists():
                if self.src.exists():
                    shutil.rmtree(self.src)
                shutil.copytree(latest_backup / "src", self.src)

            # Restaurar archivos raíz
            for file in ["settings.py", "manage.py", ".env"]:
                backup_file = latest_backup / file
                if backup_file.exists():
                    shutil.copy2(backup_file, self.root / file)

            self.log("Rollback completado", "SUCCESS")
            return True
