def move_path(self, source: str, dest: str):
        """Mueve archivo o directorio"""
        src_path = self.root / source
        dest_path = self.root / dest

        if not src_path.exists():
            self.log(f"[SKIP] No existe: {source}", "WARNING")
            return

        if self.dry_run:
            self.log(f"[DRY-RUN] Movería: {source} → {dest}", "DRY")
            return

        dest_path.parent.mkdir(parents=True, exist_ok=True)

        # Si destino existe y es directorio, mover dentro
        if dest_path.exists() and dest_path.is_dir() and src_path.is_dir():
            # Mover contenido, no el directorio mismo
            for item in src_path.iterdir():
                shutil.move(str(item), str(dest_path / item.name))
            src_path.rmdir()
        else:
            shutil.move(str(src_path), str(dest_path))

        self.log(f"Movido: {source} → {dest}", "SUCCESS")

def copy_path(self, source: str, dest: str):
        """Copia archivo o directorio"""
        src_path = self.root / source
        dest_path = self.root / dest

        if not src_path.exists():
            self.log(f"[SKIP] No existe: {source}", "WARNING")
            return

        if self.dry_run:
            self.log(f"[DRY-RUN] Copiaría: {source} → {dest}", "DRY")
            return

        dest_path.parent.mkdir(parents=True, exist_ok=True)

        if src_path.is_dir():
            shutil.copytree(src_path, dest_path, dirs_exist_ok=True)
        else:
            shutil.copy2(src_path, dest_path)

        self.log(f"Copiado: {source} → {dest}", "SUCCESS")

def delete_path(self, path: str):
        """Elimina archivo o directorio"""
        target = self.root / path

        if not target.exists():
            self.log(f"[SKIP] No existe: {path}", "WARNING")
            return

        if self.dry_run:
            self.log(f"[DRY-RUN] Eliminaría: {path}", "DRY")
            return

        if target.is_dir():
            shutil.rmtree(target)
        else:
            target.unlink()

        self.log(f"Eliminado: {path}", "SUCCESS")

def execute_migration(self, migration: Migration):
        """Ejecuta una operación de migración"""
        if migration.action == "create_dir":
            self.create_directory(migration.source)
        elif migration.action == "create_file":
            self.create_file(migration.source, migration.content)
        elif migration.action == "move":
            self.move_path(migration.source, migration.dest)
        elif migration.action == "copy":
            self.copy_path(migration.source, migration.dest)
        elif migration.action == "delete":
            self.delete_path(migration.source)

def _connect_weaviate(app_cfg: AppConfig):
    host = app_cfg.WEAVIATE_URL.replace("http://", "").replace("https://", "").split(":")[0]
    port = int(app_cfg.WEAVIATE_URL.split(":")[-1]) if ":" in app_cfg.WEAVIATE_URL else 8080
    return weaviate.connect_to_local(
        host=host,
        port=port,
        grpc_port=app_cfg.WEAVIATE_GRPC_PORT,
    )

