def _libreoffice_error_message(return_code: int, input_path: Path) -> str:
    diagnostic = ""
    if return_code == 1:
        # Check common problems
        if not input_path.exists():
            diagnostic = f"ERROR: File does not exist ({input_path})"
        elif os.access(input_path, os.R_OK) is False:
            diagnostic = f"ERROR: Insufficient permissions ({input_path})"
        else:
            diagnostic = "ERROR: General failure (possible environment issue)"
    elif return_code == 5:
        diagnostic = f"ERROR: Memory allocation failure. File too large: {input_path}"
    elif return_code == 6:
        diagnostic = f"ERROR: I/O error. Check permissions: {input_path}"
    elif return_code == 137:
        diagnostic = f"ERROR: Process terminated (likely OOM). Increase memory limits: {input_path}"
    else:
        diagnostic = f"ERROR: Unknown exit code: {return_code}"

    return f"{diagnostic} | Code: {return_code} | File: {input_path}"

async def _convert_spreadsheet_to_text(input_path: Path, output_path: Path) -> dict:
    """Convert spreadsheet formats to text using pandas."""
    try:
        if not os.access(output_path.parent, os.W_OK):
            raise PermissionError(
                f"Output directory not writable: {output_path.parent}. WORK_DIR={WORK_DIR}"
            )
        await asyncio.to_thread(_spreadsheet_to_text_sync, input_path, output_path)
        success = output_path.exists() and output_path.stat().st_size > 0
        return {
            "success": success,
            "stdout": "",
            "stderr": "",
            "error": None if success else "Spreadsheet export produced empty output",
        }
    except Exception as e:
        return {
            "success": False,
            "error": f"Spreadsheet export failed: {str(e)}",
        }

def _spreadsheet_to_text_sync(input_path: Path, output_path: Path) -> None:
    suffix = input_path.suffix.lower()

    if suffix == ".csv":
        sheets = {"Sheet1": pd.read_csv(input_path, dtype=str, keep_default_na=False)}
    else:
        engine = "openpyxl"
        if suffix == ".xls":
            engine = "xlrd"
        sheets = pd.read_excel(
            input_path,
            sheet_name=None,
            dtype=str,
            engine=engine,
        )

    with output_path.open("w", encoding="utf-8") as handle:
        for sheet_name, frame in sheets.items():
            if len(sheets) > 1:
                handle.write(f"## {sheet_name}\n")
            handle.write(frame.to_csv(index=False))
            handle.write("\n")

def get_file_metadata(file_path: Path) -> dict:
    """
    Get metadata about a file.

    Args:
        file_path: Path to the file

    Returns:
        Dictionary with file metadata
    """
    try:
        stat = file_path.stat()
        return {
            'size_bytes': stat.st_size,
            'modified_at': stat.st_mtime,
            'created_at': stat.st_ctime,
            'is_readable': os.access(file_path, os.R_OK),
            'is_writable': os.access(file_path, os.W_OK),
            'extension': file_path.suffix.lower(),
        }
    except OSError:
        return {}

def get_document_metadata(file_path: str) -> dict:
    """
    Get metadata for a document file.

    Args:
        file_path: Path to the file

    Returns:
        Dictionary with metadata
    """
    try:
        from .document_validator import get_file_metadata
        path = Path(file_path)
        return get_file_metadata(path)
    except Exception:
        return {}

def update_from_env(self):
        """Update configuration from environment variables."""
        # Max file size
        max_size = os.getenv("MAX_FILE_SIZE_MB")
        if max_size:
            try:
                self.max_file_size_mb = int(max_size)
            except ValueError:
                pass

        # OCR settings
        self.enable_ocr = os.getenv("ENABLE_OCR", "true").lower() == "true"
        self.ocr_language = os.getenv("OCR_LANGUAGE", "eng")

        # Temp directory
        temp_dir = os.getenv("WORK_DIR")
        if temp_dir:
            self.temp_dir = temp_dir

        # Concurrent limit
        concurrent = os.getenv("CONCURRENT_PROCESSES")
        if concurrent:
            try:
                self.concurrent_limit = int(concurrent)
            except ValueError:
                pass

def to_dict(self) -> dict:
        """Convert configuration to dictionary."""
        return {
            'max_file_size_mb': self.max_file_size_mb,
            'enable_ocr': self.enable_ocr,
            'ocr_language': self.ocr_language,
            'enable_validation': self.enable_validation,
            'temp_dir': self.temp_dir,
            'concurrent_limit': self.concurrent_limit,
        }

def get_process_memory_usage() -> Dict[str, float]:
    """
    Get memory usage of current process.

    Returns:
        Dictionary with process memory information
    """
    try:
        process = psutil.Process(os.getpid())
        mem_info = process.memory_info()

        return {
            'rss_mb': mem_info.rss / (1024**2),  # Resident Set Size
            'vms_mb': mem_info.vms / (1024**2),  # Virtual Memory Size
            'percent': process.memory_percent(),
        }
    except Exception:
        return {
            'rss_mb': 0,
            'vms_mb': 0,
            'percent': 0,
        }

def cleanup(self, keep_base: bool = True):
        """
        Clean up all created temporary files and directories.

        Args:
            keep_base: Whether to keep the base directory
        """
        for path in reversed(self.created_paths):
            try:
                if path.exists():
                    if path.is_file():
                        path.unlink()
                    elif path.is_dir():
                        shutil.rmtree(path)
            except (OSError, PermissionError):
                # Ignore cleanup errors
                pass

        # Clear the list
        self.created_paths.clear()

        # Remove base directory if empty and not keeping it
        if not keep_base and self.base_dir.exists():
            try:
                # Check if directory is empty
                if not any(self.base_dir.iterdir()):
                    self.base_dir.rmdir()
            except (OSError, PermissionError):
                pass

