    """Extract archive to output directory."""
    suffix = archive_path.suffix.lower()

    # Build extraction command based on archive type
    if suffix == ".zip":
        cmd = ["unzip", "-q", "-o", str(archive_path), "-d", str(output_dir)]
    elif suffix == ".7z":
