    elif suffix in [".tar", ".tgz", ".tar.gz", ".tar.xz", ".tar.bz2"]:
        cmd = ["tar", "-xf", str(archive_path), "-C", str(output_dir)]
    elif suffix == ".rar":
        cmd = ["unrar", "x", "-o+", str(archive_path), str(output_dir)]
